// Generates src/index.ts from src/{components,charts,ai,widgets}/*/index.ts. Never edit index.ts by hand.
import { readdirSync, existsSync, writeFileSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const src = join(dirname(fileURLToPath(import.meta.url)), '..', 'src');
const groups = ['components', 'charts', 'ai', 'widgets'];

const lines = [
  '// AUTO-GENERATED by scripts/gen-index.mjs — do not edit. Run `npm run gen:index`.',
  "export * from './tokens';",
  "export * from './themes';",
];
for (const g of groups) {
  const dir = join(src, g);
  if (!existsSync(dir)) continue;
  const names = readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(dir, d.name, 'index.ts')))
    .map((d) => d.name)
    .sort();
  if (names.length) lines.push('', `// ${g}`);
  for (const n of names) lines.push(`export * from './${g}/${n}';`);
}
const out = lines.join('\n') + '\n';
const file = join(src, 'index.ts');
if (!existsSync(file) || readFileSync(file, 'utf8') !== out) writeFileSync(file, out);
console.log(`gen-index: ${lines.filter((l) => l.startsWith('export * from')).length} exports`);
